<template><div class="alchemy-demo"><div class="toolbar"><div><p>阶段 2 · 等待演出</p><h1>小岐的丹房</h1></div><div class="controls"><el-radio-group v-model="variant" size="small"><el-radio-button label="night">A 夜色丹房</el-radio-button><el-radio-button label="paper">B 宣纸丹青</el-radio-button></el-radio-group><button @click="replay">重播</button><button @click="fail">模拟失败</button><button @click="offline">模拟断线</button></div></div><AlchemyStage :key="runId" :events="events" :variant="variant" :config="config"/><section class="tuning"><label v-for="control in controls" :key="control.key">{{ control.label }} <output>{{ control.value }}</output><el-slider v-model="config[control.key]" :min="control.min" :max="control.max" :step="control.step" :show-tooltip="false"/></label></section></div></template>
<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import AlchemyStage, { type AlchemyStreamEvent } from '../components/alchemy/AlchemyStage.vue'
import { alchemyVariants, type AlchemyVariant, type AlchemyVisualConfig } from '../config/alchemy-stage'
const variant = ref<AlchemyVariant>('night'); const events = ref<AlchemyStreamEvent[]>([]); const runId = ref(0); let timers: number[] = []
const config = reactive<AlchemyVisualConfig>({ ...alchemyVariants.night, palette: alchemyVariants.night.palette })
const controls = computed(() => [{ key: 'flameIntensity', label: '火焰强度', value: config.flameIntensity.toFixed(2), min: .25, max: 1, step: .01 }, { key: 'particleCount', label: '火星密度', value: String(config.particleCount), min: 0, max: 12, step: 1 }, { key: 'flameSpeed', label: '流速', value: `${config.flameSpeed.toFixed(1)}s`, min: .7, max: 3, step: .1 }, { key: 'haloRadius', label: '光晕半径', value: `${config.haloRadius}px`, min: 12, max: 64, step: 1 }, { key: 'breathSeconds', label: '呼吸频率', value: `${config.breathSeconds.toFixed(1)}s`, min: 2, max: 7, step: .1 }, { key: 'mascotMotion', label: '小岐动作', value: config.mascotMotion.toFixed(2), min: .4, max: 1.5, step: .05 }, { key: 'bubbleFrequency', label: '气泡频率', value: config.bubbleFrequency.toFixed(2), min: .5, max: 1.5, step: .05 }] as const)
const clear = () => { timers.forEach(clearTimeout); timers = [] }
const replay = () => { clear(); runId.value++; events.value = []; ['source', 'relation', 'distill', 'verify', 'compose'].forEach((step, index) => timers.push(window.setTimeout(() => { events.value = [...events.value, { type: 'step', stepId: step }]; if (index === 4) timers.push(window.setTimeout(() => events.value = [...events.value, { type: 'complete' }], 2600)) }, index * 3000 + 400))) }
const fail = () => { clear(); events.value = [...events.value, { type: 'status', status: 'failed' }] }; const offline = () => { clear(); events.value = [...events.value, { type: 'status', status: 'offline' }]; timers.push(window.setTimeout(() => events.value = [...events.value, { type: 'status', status: 'reconnected' }], 2600)) }
watch(variant, value => { Object.assign(config, alchemyVariants[value]); config.palette = alchemyVariants[value].palette; replay() }); replay(); onBeforeUnmount(clear)
</script>
<style scoped>.alchemy-demo{width:min(1220px,100%);margin:0 auto}.toolbar{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:8px 2px 18px}.toolbar p{margin:0;color:var(--qh-text-muted);font-size:11px;letter-spacing:1.8px}.toolbar h1{margin:5px 0 0;color:var(--qh-color-cream);font-size:28px;letter-spacing:1px}.controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.controls button{border:1px solid var(--qh-border);border-radius:3px;background:rgba(13,25,24,.5);color:var(--qh-text-muted);font-size:12px;padding:7px 10px}.tuning{display:grid;grid-template-columns:repeat(7,1fr);gap:14px;margin:14px 0 32px;padding:15px;border:1px solid var(--qh-border);border-radius:6px;background:rgba(14,27,25,.48)}.tuning label{display:grid;grid-template-columns:1fr auto;gap:6px;color:var(--qh-text-muted);font-size:11px}.tuning output{color:var(--qh-color-gold)}.tuning :deep(.el-slider){grid-column:1/-1}.tuning :deep(.el-slider__runway){margin:2px 0;background:rgba(255,255,255,.12)}.tuning :deep(.el-slider__bar){background:var(--qh-color-jade-d)}.tuning :deep(.el-slider__button){width:12px;height:12px;border-color:var(--qh-color-cream);background:var(--qh-color-jade)}@media(max-width:1000px){.tuning{grid-template-columns:repeat(3,1fr)}}@media(max-width:800px){.toolbar{align-items:flex-start;flex-direction:column}.controls{justify-content:flex-start}.tuning{grid-template-columns:1fr}}</style>
